{
  "summary": "For most adults with type 2 diabetes, current guidelines recommend adding a sodium‑glucose cotransporter‑2 (SGLT2) inhibitor or a glucagon‑like peptide‑1 (GLP‑1) agonist to metformin and lifestyle changes, based on high‑certainty evidence of cardiovascular and renal benefits (PMID 38639546). In addition, long‑acting GLP‑1 receptor agonists (including both injectable and oral formulations) reduce major adverse cardiovascular events, heart‑failure hospitalization, kidney events and all‑cause mortality (PMID 40156846). For patients with obesity or needing weight loss, tirzepatide (a GIP/GLP‑1 dual agonist) shows significant HbA1c and weight reduction, although most trial data are in younger populations (PMID 40975112).",
  "claims": [
    {
      "statement": "Guidelines recommend adding an SGLT2 inhibitor or GLP‑1 agonist to metformin and lifestyle as first‑line add‑on therapy for adults with inadequate glycemic control, supported by high‑certainty evidence of reduced mortality, cardiovascular events, and kidney disease progression.",
      "pmids": ["38639546"],
      "confidence": "strong"
    },
    {
      "statement": "Long‑acting GLP‑1 receptor agonists (both injectable and oral) reduce the incidence of major adverse cardiovascular events by ~14%, heart‑failure hospitalization by 14%, kidney outcomes by 17%, and all‑cause mortality by 12% in persons with type 2 diabetes.",
      "pmids": ["40156846"],
      "confidence": "moderate"
    },
    {
      "statement": "Tirzepatide 5 mg or 10 mg administered subcutaneously significantly lowers HbA1c (mean reduction ~2.3 %) and body weight (≈7–11 %) in youth‑onset type 2 diabetes, indicating its potential as a newer pharmacologic option, although pediatric data are limited.",
      "pmids": ["40975112"],
      "confidence": "moderate"
    }
  ],
  "limitations": [
    "Evidence for tirzepatide in adults with type 2 diabetes is not represented in the provided records; only pediatric data are available.",
    "Weight‑loss outcomes were not graded with GRADE in the ACP guideline, and data were insufficient for network meta‑analysis."
  ],
  "overall_grade": "moderate"
}
